/* DAA Lab 03 Q5 - SVG validation of O(n^2) special-matrix multiplication. */
#include <stdio.h>
#include <math.h>
#define MAXP 32

typedef struct{double n,m,a,d,t,n2,n3;}Row;
static double lg(double x){return log(x)/log(10.0);} 
int main(void){
 FILE*in=fopen("q5_experimental_data.dat","r");if(!in){puts("Run q5_experimental_validation first.");return 1;}Row r[MAXP];int k=0;char s[256];while(fgets(s,sizeof s,in)&&k<MAXP){if(s[0]=='#')continue;if(sscanf(s,"%lf %lf %lf %lf %lf %lf %lf",&r[k].n,&r[k].m,&r[k].a,&r[k].d,&r[k].t,&r[k].n2,&r[k].n3)==7)k++;}fclose(in);if(k<2)return 1;
 double xmax=log(r[k-1].n)/log(2.0), ymax=lg(r[k-1].n3);FILE*o=fopen("q5_special_matrix_complexity.svg","w");if(!o)return 1;
 fprintf(o,"<svg xmlns='http://www.w3.org/2000/svg' width='1200' height='700'><defs><linearGradient id='g' x1='0' x2='1'><stop stop-color='#3b0764'/><stop offset='1' stop-color='#111827'/></linearGradient></defs><rect width='1200' height='700' rx='24' fill='url(#g)'/><text x='600' y='58' fill='white' font-family='Arial' font-size='30' font-weight='700' text-anchor='middle'>Special Recursive Matrices: O(n^2) Multiplication</text><text x='600' y='90' fill='#f5d0fe' font-family='Arial' font-size='16' text-anchor='middle'>Two recursive products + quadratic block reconstruction</text><line x1='100' y1='610' x2='1100' y2='610' stroke='#64748b' stroke-width='2'/><line x1='100' y1='150' x2='100' y2='610' stroke='#64748b' stroke-width='2'/>");
 fprintf(o,"<polyline fill='none' stroke='#e879f9' stroke-width='5' points='");for(int i=0;i<k;i++){double x=100+(log(r[i].n)/log(2.0))/xmax*1000;double y=610-lg(r[i].t)/ymax*460;fprintf(o,"%.2f,%.2f ",x,y);}fprintf(o,"'/><polyline fill='none' stroke='#22c55e' stroke-width='3' stroke-dasharray='10 8' points='");for(int i=0;i<k;i++){double x=100+(log(r[i].n)/log(2.0))/xmax*1000;double y=610-lg(r[i].n2)/ymax*460;fprintf(o,"%.2f,%.2f ",x,y);}fprintf(o,"'/><polyline fill='none' stroke='#f97316' stroke-width='4' points='");for(int i=0;i<k;i++){double x=100+(log(r[i].n)/log(2.0))/xmax*1000;double y=610-lg(r[i].n3)/ymax*460;fprintf(o,"%.2f,%.2f ",x,y);}fprintf(o,"'/>");
 fprintf(o,"<rect x='720' y='108' width='365' height='110' rx='14' fill='#111827' stroke='#64748b'/><line x1='745' y1='137' x2='800' y2='137' stroke='#e879f9' stroke-width='5'/><text x='815' y='143' fill='white' font-family='Arial' font-size='15'>Measured arithmetic recurrence</text><line x1='745' y1='168' x2='800' y2='168' stroke='#22c55e' stroke-width='3' stroke-dasharray='10 8'/><text x='815' y='174' fill='white' font-family='Arial' font-size='15'>n^2 reference</text><line x1='745' y1='199' x2='800' y2='199' stroke='#f97316' stroke-width='4'/><text x='815' y='205' fill='white' font-family='Arial' font-size='15'>Classical n^3 multiplications</text><text x='600' y='660' fill='#f5d0fe' font-family='Arial' font-size='16' text-anchor='middle'>The structure is preserved under A1 +/- A2, so the two-product recurrence applies recursively.</text></svg>");fclose(o);puts("Created q5_special_matrix_complexity.svg");return 0;}
